const maximum = (arr, k) => {
    if(k == 0) return [];
    if(k >= arr.length) return arr;
    let copy = arr.slice();
    let result = [];
    let part = partition(copy, k-1);
    while(part < k){
        let temp = partition(copy, part-1);
        if(temp < k){
            result.push(copy[temp]);
            copy.splice(temp, 1);
            part = temp + 1;
        }else{
            result.push(copy[temp]);
            copy.splice(temp, 1);
            part = temp;
        }
    }
    return result;
}

