    let words = sentence.split(' ');
    let is_prime = word => word.length === 1 || word.length === 2;
    let answer = '';
    for(let i = 0; i < words.length; i++){
        if(is_prime(words[i])){
            answer += words[i] + ' ';
        }
    }
    return answer.trim();
}

